// Generated sample demonstration assets for BMI CXR-AI v2
class DemoAssets {
  static const String sampleCxrBase64 = '';
  static const String heatmapEmphysema = '';
  static const String heatmapCardiomegaly = '';
  static const String heatmapPneumonia = '';
  static const String heatmapEffusion = '';
  static const String heatmapGeneric = '';

  static String getHeatmapFor(String? label) {
    switch (label?.toLowerCase()) {
      case 'emphysema':
        return heatmapEmphysema;
      case 'cardiomegaly':
        return heatmapCardiomegaly;
      case 'pneumonia':
        return heatmapPneumonia;
      case 'effusion':
        return heatmapEffusion;
      default:
        return heatmapGeneric;
    }
  }
}
